import{_ as i,l as s,o as e,c as n,v as r,p as l,x as t,d as c,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"并发哈希表","description":"","frontmatter":{"title":"并发哈希表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/concurrent-hashmap.md","filePath":"cs/concurrent-hashmap.md","lastUpdated":1789023840000}'),p={name:"cs/concurrent-hashmap.md"};function m(u,a,E,_,A,f){const o=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="并发哈希表" tabindex="-1">并发哈希表 <a class="header-anchor" href="#并发哈希表" aria-label="Permalink to &quot;并发哈希表&quot;">​</a></h1><div class="epigraph"><p>桶级锁、分段锁、或无锁链表/CAS 槽：扩容要把迁移与查找线性化，不能当单线程再散列。</p><footer>—— 据 Herlihy and Shavit, The Art of Multiprocessor Programming；Lea, Concurrent Hash Map 设计笔记；Michael, High Performance Dynamic Lock-Free Hash Tables and List-Based Sets, PODC 2002 整理</footer></div><p><a href="/cs/hazard-pointer">上一课</a> 给了节点回收。<a href="/cs/chaining-open-address">链式与开放寻址</a>、<a href="/cs/robin-cuckoo">Robin Hood 与布谷</a> 是串行放置。<a href="/cs/concurrent-skip-list">并发跳表</a> 保序。本课不 splay。缺口是无序并发 <code>map</code>：查找热、插入扩容。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单锁哈希表随核数塌缩。分段：每段一把锁，期望冲突减。桶锁更细。无锁：每桶 Michael 无锁链表或 CAS 槽位，扩容用新表 + 迁移标志，查找可能要看两代表。缺口是<strong>扩容与 get/put 交错时仍线性化</strong>，以及 size 计数的近似 vs 精确。</p><p><span class="marginnote">Doug Lea 的 <code>ConcurrentHashMap</code>（分段 → 后来 bin + treeify + 协助迁移）是实践课。Michael PODC 2002 无锁哈希。Herlihy–Shavit 教材有整章。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找无锁或持桶锁只读。插入：锁桶或 CAS 链头。扩容：分配更大数组，线程 put 时顺便迁移一个桶（协助），避免停世界。键相等与哈希必须稳定。迭代弱一致：可以不见刚插入的，合同要写。</p>',8)),(e(),l(d,null,{default:t(()=>[h(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22h(k)%22%5D%20--%3E%20BIN%5B%22%E6%A1%B6%22%5D%0A%20%20BIN%20--%3E%20LOCK%5B%22%E6%A1%B6%2F%E6%AE%B5%E9%94%81%22%5D%0A%20%20BIN%20--%3E%20LF%5B%22%E6%97%A0%E9%94%81%E9%93%BE%20%2B%20HP%22%5D%0A%20%20RESIZE%5B%22%E6%89%A9%E5%AE%B9%22%5D%20--%3E%20HELP%5B%22%E6%9F%A5%E6%89%BE%2F%E6%8F%92%E5%85%A5%E5%8D%8F%E5%8A%A9%E8%BF%81%E7%A7%BB%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与 HAMT：持久 HAMT CAS 根适合多读；就地并发表吞吐常更高。与 ART：有序内存索引另一条线。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>假共享：相邻桶锁应填充。负载因子触发扩容，与串行相同但阈值要考虑并发插入爆发。不要在教学里要求复现数据竞争当作业。</p><p>读多写少、读侧几乎无原子：RCU 链表哈希下一课更合适。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把某语言标准库源码逐行当课程。布谷并发插入踢链更难，点名。RCU 友好结构强调写复制或发表指针。</p><p>后课默认：通用并发字典可用分段/无锁哈希。读优化链表用 RCU。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>并发哈希：细锁或无锁桶，扩容要协助迁移。</li><li>迭代常弱一致；回收用 HP/epoch。</li><li>读多写少可改 RCU 发表。</li><li>出处：Herlihy and Shavit；Lea；Michael, <em>PODC</em>, 2002。</li></ul>',9))])}const P=i(p,[["render",m]]);export{C as __pageData,P as default};
